string sampleText =
    "The quick brown fox jumps over the lazy dog. " +
    "A stitch in time saves nine. " +
    "To be or not to be that is the question. " +
    "All that glitters is not gold. " +
    "Actions speak louder than words and deeds matter more than promises. " +
    "The early bird catches the worm but the second mouse gets the cheese. " +
    "Knowledge is power and ignorance is bliss according to some philosophers.";

var analyzer = new TextAnalyzer(sampleText);

// Warmup
for (int i = 0; i < WarmupIterations; i++)
{
    analyzer.AverageWordLength();
    analyzer.WordLengthHistogram();
    analyzer.UniqueWordCount();
}

Console.WriteLine($"Runtime: {System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription}");
Console.WriteLine($"Iterations: {BenchmarkIterations}");
Console.WriteLine();

// Benchmark AverageWordLength
var sw = Stopwatch.StartNew();
for (int i = 0; i < BenchmarkIterations; i++)
    analyzer.AverageWordLength();
sw.Stop();
Console.WriteLine($"AverageWordLength:    {sw.Elapsed.TotalMilliseconds / BenchmarkIterations * 1_000_000:F1} ns/op");

// Benchmark WordLengthHistogram
sw.Restart();
for (int i = 0; i < BenchmarkIterations; i++)
    analyzer.WordLengthHistogram();
sw.Stop();
Console.WriteLine($"WordLengthHistogram:  {sw.Elapsed.TotalMilliseconds / BenchmarkIterations * 1_000_000:F1} ns/op");

// Benchmark UniqueWordCount
sw.Restart();
for (int i = 0; i < BenchmarkIterations; i++)
    analyzer.UniqueWordCount();
sw.Stop();
